const diffs = { sw: [], cw: [] };
const fixed = ['Font.', '', 'HTTPServer2Go', 'ABC', 'a1b2', 'x__y--z', 'ABCdef', 'foo2Bar', '12ab', 'A1', '1A', 'aB', 'ID.card'];
