let tdiff = 0, tcdiff = 0; const tex = [];
for (let i = 0; i < 200000; i++) {
  const s = gen(200);
  const l = lt(s, { length: 24 });
  if (l !== st(s, { length: 24 })) { tdiff++; if (tex.length < 5) tex.push(['s', s, l, st(s, { length: 24 })]); }
  if (l !== ct(s, { length: 24 })) tcdiff++;
}
console.log('truncate diffs strict', tdiff, 'compat', tcdiff, JSON.stringify(tex));

const rows = [];
let gdiff = 0;
const names = ['park','jung','choi','lee','kim'];
for (let i = 0; i < 20000; i++) {
  const n = rnd(13); const arr = [];
  for (let j = 0; j < n; j++) arr.push({ id: rnd(10), name: names[rnd(5)], age: 18 + rnd(43) });
  const l = JSON.stringify(lg(arr, 'age'));
  if (l !== JSON.stringify(sg(arr, r => String(r.age)))) gdiff++;
  if (l !== JSON.stringify(cg(arr, 'age'))) gdiff += 1000000;
}
console.log('groupBy diffs (strict w/ String key, plus compat*1e6):', gdiff);
